__NUXT_JSONP__("/rumbo-democratico/publicaciones", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{posts:[{slug:"manual_de_buenas_practicas_para_la_apertura_de_datos_abiertos",title:"Manual de buenas prácticas para la apertura de datos abiertos",date:"2025-07-30T18:06:18.941Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffdb260da-1a3a-4b40-8237-ebe3ec935e42\u002F","img-alt":"Datos abiertos",autor:"Dalia Toledo y Teresa López Barajas",category:a,extracto:"Este manual tiene como propósito ofrecer una guía práctica y accesible para los servidores públicos que participan en los procesos de apertura de sus instituciones, ya que a través de conceptos clave, recomendaciones puntuales y buenas prácticas documentadas, buscamos fortalecer las capacidades institucionales para garantizar que los datos que se abren cumplan con los principios de calidad, utilidad, accesibilidad y sostenibilidad.",file:"https:\u002F\u002Fucarecdn.com\u002Ffd8056dd-6c4a-4c08-abc5-4db9edfcdc93\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fmanual_de_buenas_practicas_para_la_apertura_de_datos_abiertos",extension:c,createdAt:e,updatedAt:e},{slug:"analisis_de_las_propuestas_de_claudia_sheinbaum_en_materia_de_anticorrupcion_finanzas_publicas_adaptacion_al_cambio_climatico_y_politica_de_cuidados",title:f,date:"2024-08-06T21:44:32.127Z",img:"https:\u002F\u002Fucarecdn.com\u002F2b417d06-8f0a-4ec5-974f-ff6ea055dd26\u002F","img-alt":f,autor:g,category:a,extracto:"En Ethos Innovación en Políticas Públicas nos dimos a la tarea de analizar las propuestas de la próxima presidenta en materia de combate a la corrupción, finanzas públicas, adaptación al cambio climático y políticas de cuidados.",file:"https:\u002F\u002Fucarecdn.com\u002Fb3e060fb-9374-4c9a-a83c-6cd0c917f2dc\u002F",tags:[],toc:[],dir:b,path:"\u002Fpublicaciones\u002Fanalisis_de_las_propuestas_de_claudia_sheinbaum_en_materia_de_anticorrupcion_finanzas_publicas_adaptacion_al_cambio_climatico_y_politica_de_cuidados",extension:c,createdAt:h,updatedAt:h},{slug:"polarizacion_politica_un_fenomeno_que_vuelve_a_ser_tendencia",title:i,date:"2023-05-29T20:50:02.445Z",img:"https:\u002F\u002Fucarecdn.com\u002F6b405cef-c423-4b38-b1e0-3ef3e39a27dc\u002F","img-alt":i,autor:"Javier González",category:a,extracto:"En los últimos años América Latina ha experimentado un incremento en la polarización1 política. El malestar social, las contiendas electorales reñidas y el estancamiento legislativo a menudo se atribuyen a los altos niveles de polarización.",file:"https:\u002F\u002Fucarecdn.com\u002F596e220d-21ae-4a43-ae48-d36f3dc2e4a4\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fpolarizacion_politica_un_fenomeno_que_vuelve_a_ser_tendencia",extension:c,createdAt:"2023-10-11T18:18:44.378Z",updatedAt:d},{slug:"radar_ethos_2023",title:j,date:"2023-04-28T16:53:53.337Z",img:"https:\u002F\u002Fucarecdn.com\u002F6e21ba10-d2d8-4a69-be6c-20a6ecb1ebe0\u002F","img-alt":j,autor:g,category:a,extracto:"En su inicio, el Poder Ejecutivo planteaba una serie de modificaciones que darían como resultado un país más justo, equitativo, con finanzas públicas sanas y menos corrupción. Sin embargo, la esperanza de un cambio se ha ido diluyendo pues la realidad nos muestra que aún hay mucho por hacer para lograr estos objetivos.",file:"https:\u002F\u002Fucarecdn.com\u002Fdd72c5c5-78a9-4aaf-9866-0eaf6e89665e\u002F",toc:[],dir:b,path:"\u002Fpublicaciones\u002Fradar_ethos_2023",extension:c,createdAt:d,updatedAt:d}],total:[{},{},{},{}]}],fetch:{},mutations:[]}}("rumbo-democratico","\u002Fpublicaciones",".md","2023-10-11T18:18:44.379Z","2025-11-25T01:24:03.297Z","Análisis de las propuestas de Claudia Sheinbaum en materia de anticorrupción, finanzas públicas, adaptación al cambio climático y política de cuidados","Ethos","2024-10-02T22:32:44.108Z","Polarización política: un fenómeno que vuelve a ser tendencia","Radar Ethos 2023")));